+ const rightGrass=p('#70884a',`M1770 634C1790 634 1808 640 1834 641L1903 640 1989 642 2055 640 2101 642 ${R} 641V644L2101 645 2055 643 1989 645 1903 643 1834 644C1808 644 1790 641 1770 641Z`);
